-- ============================================================================
-- MIG664 · Tarjeta Aramco: km históricos desde Navixy (Fase 3 de rendimiento)
-- ----------------------------------------------------------------------------
-- El km diario del GPS en SICOM (activo_horas_dia) existe solo desde
-- mediados de septiembre-2026, así que ene-ago no tenían km/L. Navixy
-- (Radicom) sí guarda el kilometraje por día (tracker/stats/mileage/read).
-- Contra lo que SICOM ya tenía, cuadra en 0-1 % por vehículo (KVDK-20 -8 %,
-- por un día sin dato en SICOM).
--
-- Con meses de pocas cargas, un tramo suelto daba un km/L falso: el km/L del
-- mes exige ahora 2 tramos medidos y 400 km (antes 100 km).
--
-- Carga ÚNICA (28-10-2026), sin cron ni edge function nueva: 1.883 días de
-- 11 vehículos con tarjeta, desde dic-2025 hasta el día anterior al primer
-- dato real de cada uno. km_fin = odómetro reconstruido hacia atrás desde el
-- primer odómetro real (primer odómetro − km de los días siguientes), así los
-- tramos entre cargas se calculan igual que con el dato real. En VRST-19 el
-- contador se fijó más bajo al instalarlo, por eso su odómetro histórico
-- llega a ser negativo: solo importan las diferencias.
--
-- Va en una tabla aparte (no en activo_horas_dia) para no tocar horas,
-- preventivas ni certificados, que leen esa tabla. Solo la usan las vistas
-- de combustible, por medio de v_combustible_km_dia.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.combustible_km_historico (
    activo_id   UUID NOT NULL REFERENCES public.activos(id) ON DELETE CASCADE,
    fecha       DATE NOT NULL,
    km_fin      NUMERIC NOT NULL,          -- odómetro reconstruido al cierre del día
    km          NUMERIC NOT NULL CHECK (km >= 0),   -- km del día según Navixy
    fuente      TEXT NOT NULL DEFAULT 'navixy',
    PRIMARY KEY (activo_id, fecha)
);
ALTER TABLE public.combustible_km_historico ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS pol_comb_km_hist_sel ON public.combustible_km_historico;
CREATE POLICY pol_comb_km_hist_sel ON public.combustible_km_historico
    FOR SELECT TO authenticated USING (public.fn_costos_operacion_puede_ver());
REVOKE ALL ON public.combustible_km_historico FROM anon, authenticated;
GRANT SELECT ON public.combustible_km_historico TO authenticated;

