-- km por día para combustible: el real de SICOM y, antes de él, el de Navixy
-- (la carga histórica termina el día antes del primer dato real). Mismo
-- criterio que v_activo_horas_dia (diferencia contra el día anterior con dato),
-- pero con una ventana en vez de una subconsulta por fila: la vista de cargas
-- la consulta por cada carga.
CREATE OR REPLACE VIEW public.v_combustible_km_dia AS
SELECT x.activo_id, x.fecha, x.km_fin,
       CASE WHEN x.km_ant IS NULL OR x.km_fin IS NULL THEN NULL
            WHEN x.km_fin - x.km_ant < 0 OR x.km_fin - x.km_ant > 1500 * (x.fecha - x.fecha_ant) THEN NULL
            ELSE round(x.km_fin - x.km_ant) END AS km
  FROM (SELECT u.*, lag(u.km_fin) OVER w AS km_ant, lag(u.fecha) OVER w AS fecha_ant
          FROM (SELECT activo_id, fecha, km_fin FROM activo_horas_dia
                UNION ALL
                SELECT activo_id, fecha, km_fin FROM combustible_km_historico) u
        WINDOW w AS (PARTITION BY u.activo_id ORDER BY u.fecha)) x;

COMMENT ON VIEW public.v_combustible_km_dia IS
    'km por equipo y día para rendimiento de combustible: GPS de SICOM + histórico Navixy antes de él. MIG664.';
REVOKE ALL ON public.v_combustible_km_dia FROM anon;
GRANT SELECT ON public.v_combustible_km_dia TO authenticated;

CREATE OR REPLACE VIEW public.v_combustible_tarjeta_cargas AS
WITH c AS (
    SELECT c.*, coalesce(a.patente, c.patente) AS patente_ver, a.tipo::text AS tipo_sicom,
           CASE WHEN a.tipo_equipamiento::text = 'aljibe_combustible' THEN 'abastecimiento' ELSE 'flota' END AS grupo,
           EXISTS (SELECT 1 FROM gps_activo_mapeo g WHERE g.activo_id = c.activo_id) AS tiene_gps,
           o.km_fin AS odometro_gps, o.fecha AS odometro_fecha,
           -- [MIG662] capacidad del estanque y km GPS del día de la carga
           coalesce(a.capacidad_estanque_l,
                    CASE WHEN c.tipo_vehiculo ILIKE 'camioneta%' THEN 80
                         WHEN c.tipo_vehiculo ILIKE 'cami%' THEN 450 ELSE 80 END) AS capacidad_l,
           hd.km AS km_dia, w30.km AS km_30d, w30.dias AS dias_gps_30d, l30.litros AS litros_30d
      FROM combustible_tarjeta_cargas c
      LEFT JOIN activos a ON a.id = c.activo_id
      -- [MIG660] Fuera del análisis (p. ej. la camioneta de gerencia).
      LEFT JOIN combustible_tarjeta_excluidas x ON x.patente = c.patente
      LEFT JOIN LATERAL (
            -- [MIG664] odómetro real o, antes de que existiera, el reconstruido desde Navixy
            SELECT h.km_fin, h.fecha FROM (
                   SELECT a.km_fin, a.fecha FROM activo_horas_dia a
                    WHERE a.activo_id = c.activo_id AND a.fecha < c.fecha_hora::date AND a.km_fin > 0
                   UNION ALL
                   SELECT k.km_fin, k.fecha FROM combustible_km_historico k
                    WHERE k.activo_id = c.activo_id AND k.fecha < c.fecha_hora::date) h
             ORDER BY h.fecha DESC LIMIT 1) o ON c.activo_id IS NOT NULL
      LEFT JOIN v_combustible_km_dia hd ON hd.activo_id = c.activo_id AND hd.fecha = c.fecha_hora::date
      -- [MIG662] ventana de 30 días, pero nunca antes de que el vehículo tuviera km GPS
      -- (si no, se suman cargas de días sin km y todo parece «sin explicar»).
      LEFT JOIN LATERAL (
            SELECT greatest(c.fecha_hora::date - 29, least(
                     (SELECT min(h.fecha) FROM activo_horas_dia h WHERE h.activo_id = c.activo_id AND h.km_fin > 0),
                     (SELECT min(k.fecha) FROM combustible_km_historico k WHERE k.activo_id = c.activo_id))) AS desde
           ) g ON c.activo_id IS NOT NULL
      LEFT JOIN LATERAL (
            SELECT sum(d.km) AS km, (c.fecha_hora::date - g.desde + 1) AS dias FROM v_combustible_km_dia d
             WHERE d.activo_id = c.activo_id
               AND d.fecha >= g.desde AND d.fecha <= c.fecha_hora::date) w30 ON g.desde IS NOT NULL
      LEFT JOIN LATERAL (
            SELECT sum(c2.litros) AS litros FROM combustible_tarjeta_cargas c2
             WHERE c2.patente = c.patente AND c2.fecha_hora::date >= g.desde AND c2.fecha_hora <= c.fecha_hora) l30
             ON g.desde IS NOT NULL
     WHERE x.patente IS NULL
), t AS (
    SELECT c.*,
           CASE WHEN c.odometro_fecha >= c.fecha_hora::date - 3 THEN c.odometro_gps END AS odo,
           count(*) OVER (PARTITION BY c.patente, c.fecha_hora::date) AS cargas_dia,
           sum(c.litros) OVER (PARTITION BY c.patente, c.fecha_hora::date) AS litros_dia,
           row_number() OVER (PARTITION BY c.patente, c.fecha_hora::date ORDER BY c.fecha_hora DESC) AS ultima_del_dia
      FROM c
), k AS (
    SELECT t.*,
           t.odo - lag(t.odo) OVER (PARTITION BY t.patente ORDER BY t.fecha_hora) AS km_bruto,
           lag(t.fecha_hora) OVER (PARTITION BY t.patente ORDER BY t.fecha_hora) AS carga_anterior
      FROM t
), k2 AS (
    SELECT k.*,
           CASE WHEN k.km_bruto BETWEEN 0 AND 5000 THEN round(k.km_bruto) END AS km_tramo
      FROM k
), r AS (
    SELECT k2.*,
           CASE WHEN k2.km_tramo > 0 AND k2.litros > 0 THEN round(k2.km_tramo / k2.litros, 1) END AS km_l_tramo
      FROM k2
), est AS (
    SELECT estacion, count(*) AS n,
           percentile_cont(0.5) WITHIN GROUP (ORDER BY gps_lat) AS lat,
           percentile_cont(0.5) WITHIN GROUP (ORDER BY gps_lng) AS lng
      FROM combustible_tarjeta_cargas WHERE gps_lat IS NOT NULL GROUP BY estacion
), med AS (
    SELECT patente, count(*) AS n, percentile_cont(0.5) WITHIN GROUP (ORDER BY km_l_tramo) AS km_l
      FROM r WHERE km_l_tramo IS NOT NULL GROUP BY patente
), r2 AS (   -- [MIG662] litros que no explican ni los km de 30 días ni un estanque completo
    SELECT r.*, med.n AS med_n, med.km_l AS med_km_l,
           CASE WHEN r.grupo = 'flota' AND med.n >= 4 AND r.dias_gps_30d >= 20 AND med.km_l > 0
                THEN r.litros_30d - (r.km_30d / med.km_l * 1.2 + r.capacidad_l * 1.1) END AS litros_sin_explicar_30d
      FROM r LEFT JOIN med ON med.patente = r.patente
)
SELECT r.id, r.importacion_id, r.cod_autorizacion, r.fecha_hora, r.patente, r.patente_ver,
       r.activo_id, r.tipo_vehiculo, r.tiene_gps, r.producto, r.estacion, r.comuna, r.tarjeta,
       r.rut_chofer, r.litros, r.pizarra_l, r.total_pago, r.guia_despacho,
       r.gps_lat, r.gps_lng, r.gps_dif_min, r.odo AS odometro_gps, r.carga_anterior, r.km_tramo, r.km_l_tramo,
       round(r.med_km_l::numeric, 1) AS km_l_mediana,
       CASE WHEN est.n >= 3 AND r.gps_lat IS NOT NULL
            THEN round(public.fn_distancia_haversine(r.gps_lat, r.gps_lng, est.lat::numeric, est.lng::numeric) / 1000, 1) END
            AS dist_estacion_km,
       array_remove(ARRAY[
           CASE WHEN r.activo_id IS NULL THEN 'sin_ficha' END,
           CASE WHEN r.activo_id IS NOT NULL AND NOT r.tiene_gps THEN 'sin_gps' END,
           CASE WHEN est.n >= 3 AND r.gps_lat IS NOT NULL
                 -- metros; la lectura GPS puede estar hasta 90 min de la carga: se toleran
                 -- 5 km + 1,2 km por minuto de diferencia (un vehículo a ~70 km/h).
                 AND public.fn_distancia_haversine(r.gps_lat, r.gps_lng, est.lat::numeric, est.lng::numeric)
                     > (5 + 1.2 * coalesce(r.gps_dif_min, 0)) * 1000
                THEN 'fuera_estacion' END,
           -- [MIG662] capacidad real del estanque + 10 % de cuello de llenado.
           CASE WHEN r.grupo = 'flota' AND r.litros > r.capacidad_l * 1.1 THEN 'sobre_estanque' END,
           -- Con odómetro diario, dos cargas el mismo día dan 0 km: eso es «dos_cargas_dia», no esto.
           CASE WHEN r.grupo = 'flota' AND r.km_tramo IS NOT NULL AND r.km_tramo < 5 AND r.litros >= 15
                 AND r.carga_anterior::date < r.fecha_hora::date THEN 'sin_movimiento' END,
           -- [MIG662] 30 días: cargó más de lo que gastó andando + un estanque.
           CASE WHEN r.litros_sin_explicar_30d > 0 THEN 'rendimiento_bajo' END,
           CASE WHEN r.cargas_dia > 1 THEN 'dos_cargas_dia' END,
           -- [MIG662] en el día cargó más de lo que cabe + lo que gastó andando ese día.
           CASE WHEN r.grupo = 'flota' AND r.cargas_dia > 1 AND r.ultima_del_dia = 1
                 AND r.litros_dia > r.capacidad_l * 1.1
                                    + coalesce(r.km_dia, 0) / coalesce(nullif(r.med_km_l, 0), 10) * 1.3
                THEN 'litros_dia_excede' END
       ], NULL) AS alertas,
       r.grupo,
       r.capacidad_l, round(r.litros_dia, 1) AS litros_dia, round(r.km_dia) AS km_dia,
       round(r.litros_30d, 1) AS litros_30d, round(r.km_30d) AS km_30d,
       round(r.litros_sin_explicar_30d::numeric, 1) AS litros_sin_explicar_30d
  FROM r2 r
  LEFT JOIN est ON est.estacion = r.estacion
 WHERE public.fn_costos_operacion_puede_ver();

GRANT SELECT ON public.v_combustible_tarjeta_cargas TO authenticated;

CREATE OR REPLACE VIEW public.v_combustible_rendimiento_mes AS
-- km/L de la tarjeta = km de los tramos ÷ litros de esos mismos tramos (lleno a
-- lleno). Así un mes con días sin GPS no da un rendimiento falso: solo cuenta lo
-- que tiene odómetro en las dos puntas.
WITH tar AS (
    SELECT c.activo_id, c.patente, max(c.tipo_vehiculo) AS tipo,
           date_trunc('month', c.fecha_hora)::date AS mes,
           count(*) AS cargas, sum(c.litros) AS litros, sum(c.total_pago) AS monto,
           sum(c.km_tramo) AS km_tramos,
           sum(c.litros) FILTER (WHERE c.km_tramo IS NOT NULL) AS litros_tramos,
           sum(c.total_pago) FILTER (WHERE c.km_tramo IS NOT NULL) AS monto_tramos,
           count(*) FILTER (WHERE c.km_tramo IS NOT NULL) AS cargas_medidas,
           max(c.grupo) AS grupo
      FROM v_combustible_tarjeta_cargas c
     GROUP BY 1, 2, 4
), precio AS (   -- $/L diésel pagado con la tarjeta, por mes
    SELECT date_trunc('month', fecha_hora)::date AS mes, sum(total_pago) / nullif(sum(litros), 0) AS pl
      FROM combustible_tarjeta_cargas WHERE producto ILIKE '%diesel%' GROUP BY 1
), km AS (
    SELECT d.activo_id, date_trunc('month', d.fecha)::date AS mes,
           sum(d.km) AS km, count(d.km) AS dias_gps
      FROM v_combustible_km_dia d   -- [MIG664] con los km históricos de Navixy
     WHERE d.activo_id IN (SELECT activo_id FROM combustible_tarjeta_cargas WHERE activo_id IS NOT NULL)
     GROUP BY 1, 2
), ren AS (
    SELECT c.activo_id, date_trunc('month', c.fecha)::date AS mes,
           sum(c.litros) AS litros, sum(c.km) AS km, sum(c.horas) AS horas,
           sum(c.litros_ralenti) AS litros_ralenti, count(c.litros) AS dias_gps
      FROM v_activo_consumo_dia c WHERE c.litros IS NOT NULL
     GROUP BY 1, 2
)
SELECT 'tarjeta'::text AS fuente, t.activo_id, coalesce(a.patente, t.patente) AS patente,
       t.tipo, t.mes, t.cargas, round(t.litros, 1) AS litros, round(t.monto) AS monto, true AS monto_real,
       round(k.km) AS km_gps, k.dias_gps, NULL::numeric AS horas, NULL::numeric AS litros_ralenti,
       t.cargas_medidas, round(t.km_tramos) AS km_medidos,
       CASE WHEN t.grupo = 'flota' AND t.km_tramos >= 400 AND t.cargas_medidas >= 2 THEN round(t.km_tramos / nullif(t.litros_tramos, 0), 1) END AS km_l,
       CASE WHEN t.grupo = 'flota' AND t.km_tramos >= 400 AND t.cargas_medidas >= 2 THEN round(t.monto_tramos / t.km_tramos) END AS costo_km,
       t.grupo
  FROM tar t
  LEFT JOIN activos a ON a.id = t.activo_id
  LEFT JOIN km k ON k.activo_id = t.activo_id AND k.mes = t.mes
 WHERE public.fn_costos_operacion_puede_ver()
UNION ALL
SELECT 'computador', r.activo_id, a.patente, a.tipo::text, r.mes, NULL, round(r.litros, 1),
       round(r.litros * coalesce(p.pl, (SELECT pl FROM precio ORDER BY mes DESC LIMIT 1))), false,
       round(r.km), r.dias_gps, round(r.horas, 1), round(r.litros_ralenti, 1),
       r.dias_gps, round(r.km),
       round(r.km / nullif(r.litros, 0), 2),
       round(r.litros * coalesce(p.pl, (SELECT pl FROM precio ORDER BY mes DESC LIMIT 1)) / nullif(r.km, 0)),
       'flota'
  FROM ren r
  JOIN activos a ON a.id = r.activo_id
  LEFT JOIN precio p ON p.mes = r.mes
 WHERE public.fn_costos_operacion_puede_ver();

REVOKE ALL ON public.v_combustible_tarjeta_cargas, public.v_combustible_rendimiento_mes FROM anon;
GRANT SELECT ON public.v_combustible_rendimiento_mes TO authenticated;

SELECT a.patente, count(*) AS dias, min(k.fecha) AS desde, max(k.fecha) AS hasta, round(sum(k.km)) AS km
  FROM public.combustible_km_historico k JOIN public.activos a ON a.id = k.activo_id
 GROUP BY 1 ORDER BY 1;
